    - {do: "User approved the spec", ok: true}
    - {do: "grade_calc.py implemented, boundary tests pass", check: "cmd: python3 -m unittest discover -s tests"}
    - {do: "Gate passes", check: "cmd: python3 -m forgemyspec gate forgemyspec-bundle/grade-calc"}
  evidence: "gate RESULT: PASS, 6 boundary tests"
